"""Infer the likely cause of holds whose post names none, from the weather, the date and the cause words in the day's other posts.
Observed and inferred stay separate: this writes data/derived/cause_inferred.csv and docs/CAUSES.md; it never edits lift_days.csv.
Method: one-vs-rest logistic regression per cause family, trained on holds whose post names exactly one family (wind, patrol/avalanche, mechanical, weather),
scored leave-one-winter-out so every accuracy figure is on a winter the model never saw. Needs numpy (python3 -I with the project's venv).
usage: python3 -I scripts/infer_causes.py   (run after build_dataset.py)"""
import csv, os, math, collections
import numpy as np
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
rows = list(csv.DictReader(open(os.path.join(ROOT, "data", "derived", "lift_days.csv"))))
rows = [r for r in rows if r["in_season"] == "1"]
FAM = ["wind", "patrol", "mechanical", "weather"]; KEY = {"wind": "held_wind", "patrol": "held_patrol", "mechanical": "held_mech", "weather": "held_weather"}
def num(x, d=0.0): return float(x) if x not in ("", None) else d
def hour(t): return int(t[:2]) + int(t[3:5]) / 60 if t else 9.0
def feats(r):
    m = int(r["date"][5:7]); spring = 1.0 if m in (4, 5) else 0.0
    return [num(r["day_gust"]), num(r["sib_h60"]), num(r["new_snow24"]), num(r["swe24"]), num(r["avy"], 2.0), num(r["temp_base"], 30.0), spring, hour(r["first_event"]),
            float(num(r["day_avy_control"]) > 0), float(num(r["day_power"]) > 0), float(num(r["day_lightning"]) > 0), float(num(r["day_ice"]) > 0), float(num(r["day_vis"]) > 0), float(num(r["day_mech"]) > 0), float(num(r["day_flood"]) > 0), float(r["closed_all"] == "1"), num(r["nws_storm_any"]), num(r["nws_wind_any"]), num(r["gust_prior3h"], num(r["day_gust"]))]
NAMES = ["crest gust", "hours at 60+", "new snow", "snow water", "avalanche danger", "base temperature", "April-May", "hour of first post", "avalanche-control post that day", "power post that day", "lightning post that day", "ice post that day", "visibility post that day", "mechanical post that day", "flood or road post that day", "whole-mountain closure", "NWS storm alert", "NWS wind alert", "gust in the 3 hours before the post"]
H = [r for r in rows if r["held"] == "1"]
def stated(r): return [f for f in FAM if r[KEY[f]] == "1"]
train_rows = [r for r in H if len(stated(r)) == 1]; unst = [r for r in H if not stated(r)]
def fit(X, y, lam=1.0, it=300):
    mu, sd = X.mean(0), X.std(0) + 1e-9; Z = np.c_[np.ones(len(X)), (X - mu) / sd]; b = np.zeros(Z.shape[1]); R = np.eye(Z.shape[1]) * lam; R[0, 0] = 0
    for _ in range(it):
        p = 1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))); W = p * (1 - p)
        g = Z.T @ (y - p) - R @ b; Hh = Z.T @ (Z * W[:, None]) + R + 1e-8 * np.eye(len(b)); st = np.linalg.solve(Hh, g); b += st
        if np.abs(st).max() < 1e-7: break
    return b, mu, sd
def prob(m, X): b, mu, sd = m; return 1 / (1 + np.exp(-np.clip(np.c_[np.ones(len(X)), (X - mu) / sd] @ b, -30, 30)))
def fit_all(rs):
    X = np.array([feats(r) for r in rs]); lab = [stated(r)[0] for r in rs]
    return {f: fit(X, np.array([1.0 if l == f else 0.0 for l in lab])) for f in FAM}
def predict(models, rs):
    X = np.array([feats(r) for r in rs]); P = np.column_stack([prob(models[f], X) for f in FAM]); return P / P.sum(1, keepdims=True)
WINT = sorted({r["winter"] for r in train_rows}); P_lo = np.zeros((len(train_rows), len(FAM)))
for W in WINT:
    te = [i for i, r in enumerate(train_rows) if r["winter"] == W]; tr = [r for r in train_rows if r["winter"] != W]
    if len(tr) < 50 or not te: continue
    P_lo[te] = predict(fit_all(tr), [train_rows[i] for i in te])
truth = np.array([FAM.index(stated(r)[0]) for r in train_rows]); pred = P_lo.argmax(1); top = P_lo.max(1)
acc = float((pred == truth).mean()); base = max(collections.Counter(truth).values()) / len(truth)
# holds whose post names two or more families: they are not used to learn; score whether the model's top family is one of the families named
multi = [r for r in H if len(stated(r)) >= 2]; m_hit = 0; m_n = 0
for W in WINT:
    te = [r for r in multi if r["winter"] == W]; tr = [r for r in train_rows if r["winter"] != W]
    if not te or len(tr) < 50: continue
    Pm = predict(fit_all(tr), te)
    for r, pm in zip(te, Pm): m_n += 1; m_hit += FAM[int(pm.argmax())] in stated(r)
models = fit_all(train_rows); P_un = predict(models, unst); best = P_un.argmax(1); bp = P_un.max(1)
out = os.path.join(ROOT, "data", "derived", "cause_inferred.csv")
with open(out, "w", newline="") as fh:
    w = csv.writer(fh); w.writerow(["winter", "date", "lift", "cause_inferred", "cause_inferred_p", "confident"] + ["p_" + f for f in FAM])
    for r, p, b, q in zip(unst, P_un, best, bp): w.writerow([r["winter"], r["date"], r["lift"], FAM[b], round(float(q), 3), int(q >= .6)] + [round(float(x), 3) for x in p])
conf = bp >= .6
md = ["# Inferred causes for holds whose post names none", "",
      "Generated by `python3 -I scripts/infer_causes.py`. **Inferred, not observed**: the observed `cause` fields are never changed. Output: `data/derived/cause_inferred.csv`.", "",
      "## What it does", "",
      f"- {len(H):,} in-season hold or closure lift-days. {len(train_rows):,} have a post that names exactly one cause family (wind, patrol or avalanche control, mechanical, weather); {len(unst):,} name none.",
      "- For each cause family a logistic regression is fitted on the named holds, using: crest gust, hours at 60 mph or more, new snow, snow water, avalanche danger, base temperature, spring, hour of the first post, cause words in the day's OTHER posts (avalanche control, power, lightning, ice, visibility, mechanical, flooding or road), whether the whole mountain closed, National Weather Service storm and wind alerts, and the strongest gust in the three hours before the post.",
      "- Accuracy is measured leave-one-winter-out on the named holds: each winter is scored by a model that never saw it.", "",
      "## How well it works", "",
      f"- Right on {100*acc:.0f}% of named holds, against {100*base:.0f}% for always guessing the most common family. Called with probability 0.6 or more: {100*float((pred == truth)[top >= .6].mean()):.0f}% right, on {100*float((top >= .6).mean()):.0f}% of holds.", "",
      "| Named cause | Holds | Recovered by the model |", "|---|---|---|"]
for i, f in enumerate(FAM): md.append(f"| {f} | {int((truth == i).sum())} | {100*float((pred[truth == i] == i).mean()):.0f}% |")
# wind named alone versus with other causes (the single `cause` field keeps only the first family, wind first)
_T = ("avalanche", "snow", "ice", "visibility", "lightning", "power", "flood", "rain", "grooming")
def _others(r): return sum(r.get("tag_" + t) == "1" for t in _T) + int(r["held_patrol"] == "1") + int(r["held_mech"] == "1") + int(r["held_weather"] == "1")
_w = [r for r in H if r["held_wind"] == "1"]; _alone = [r for r in _w if _others(r) == 0]
md += ["", "## Wind named alone or with other causes", "",
       f"- {len(_w):,} of the {len(H):,} holds name wind. {len(_alone):,} ({100*len(_alone)/max(len(_w),1):.0f}%) name wind alone; {len(_w)-len(_alone):,} ({100*(len(_w)-len(_alone))/max(len(_w),1):.0f}%) also name another cause (avalanche control, snow, ice, visibility, lightning, power, flooding, rain, grooming, patrol, mechanical or weather).",
       "- The single `cause` field keeps the first family found (wind first), so wind is credited whenever it is mentioned. Read the wind share as an upper bound; the post-level `cause_tags` hold every cause named.", ""]
md += ["", f"- Holds whose post names two or more families ({len(multi):,}) are left out of the learning. Tested on them the same way, the model's top family is one of the families the post names in {100*m_hit/max(m_n,1):.0f}% of {m_n:,} cases (a guess at random among the four would be about half).", ""]
md += ["", "## What the unstated holds look like", "", "| Inferred cause | Unstated holds | Of those, confident (0.6+) |", "|---|---|---|"]
for i, f in enumerate(FAM): md.append(f"| {f} | {int((best == i).sum())} ({100*float((best == i).mean()):.0f}%) | {int(((best == i) & conf).sum())} |")
md += ["", f"{int(conf.sum())} of {len(unst):,} unstated holds ({100*float(conf.mean()):.0f}%) get a confident inferred cause; the rest stay unexplained.", "",
       "## Limits", "",
       "- The model learns what named holds look like, so it assumes unstated holds come from the same mix of causes. If operators skip naming a cause for a particular reason, that assumption fails.",
       "- Weather families overlap: a hold named \"weather\" and one named \"wind\" can sit on the same day.",
       "- Patrol includes avalanche control and snow safety. Whole-mountain closures with no cause word are mostly inferred as wind or weather by construction.",
       "- Use the inferred cause for exploration and for filling gaps in charts. Do not quote it as what the operators said."]
open(os.path.join(ROOT, "docs", "CAUSES.md"), "w").write("\n".join(md) + "\n")
print(f"named {len(train_rows)}, unstated {len(unst)}; leave-one-winter-out accuracy {acc:.3f} (baseline {base:.3f}); confident share {float(conf.mean()):.2f}")
